changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_player_profiles_geo
    ON player_profiles (province, city, barangay);

CREATE INDEX IF NOT EXISTS idx_clubs_geo
    ON clubs (province, city, barangay);

CREATE INDEX IF NOT EXISTS idx_activities_public_created
    ON activities (created_at DESC)
    WHERE visibility = 'public';

changeSet.rollback:
DROP INDEX IF EXISTS idx_activities_public_created;
DROP INDEX IF EXISTS idx_clubs_geo;
DROP INDEX IF EXISTS idx_player_profiles_geo;
